sys_security_acl.script:
var email = gs.getUser().getEmail();
var custGr = new GlideRecord('x_2056099_indust_0_cust_master');
custGr.addQuery('primary_contact_email', email);
custGr.addActiveQuery();
custGr.setLimit(1);
custGr.query();
if (custGr.next()) {
    answer = (current.customer_order.customer == custGr.getUniqueValue());
} else {
    answer = false;
}
